use serde::Serialize;use std::{env,fs,path::PathBuf,process::Command};
#[derive(Serialize)]struct Status{os:String,arch:String,godot:Option<String>,ollama:bool,comfyui:bool,project_count:usize}
fn home()->PathBuf{env::var_os("USERPROFILE").or_else(||env::var_os("HOME")).map(PathBuf::from).unwrap_or_else(||PathBuf::from("."))}fn root()->PathBuf{home().join("AI-Game-Maker-Projects")}fn cmd(n:&str)->Option<String>{let c=if cfg!(windows){Command::new("where").arg(n).output()}else{Command::new("sh").args(["-lc",&format!("command -v {n}")]).output()};c.ok().filter(|x|x.status.success()).map(|x|String::from_utf8_lossy(&x.stdout).lines().next().unwrap_or("").trim().to_string()).filter(|x|!x.is_empty())}
#[tauri::command]fn environment_status()->Result<Status,String>{fs::create_dir_all(root()).map_err(|e|e.to_string())?;let godot=cmd("godot").or_else(||cmd("godot4"));let count=fs::read_dir(root()).map(|r|r.filter_map(Result::ok).filter(|e|e.path().is_dir()).count()).unwrap_or(0);Ok(Status{os:env::consts::OS.into(),arch:env::consts::ARCH.into(),godot,ollama:cmd("ollama").is_some(),comfyui:std::net::TcpStream::connect("127.0.0.1:8188").is_ok(),project_count:count})}
fn clean(s:&str)->String{s.chars().map(|c|if c.is_ascii_alphanumeric()||c=='-'||c=='_'{'c'}else{'_'}).collect::<String>().trim_matches('_').chars().take(64).collect()}
#[tauri::command]fn create_project(name:String,prompt:String,mode:String)->Result<String,String>{let n=clean(&name);if n.is_empty(){return Err("Projektname fehlt".into())}fs::create_dir_all(root().join(&n).join("scripts")).map_err(|e|e.to_string())?;let r=root().join(&n);let node=if mode=="3D"{"Node3D"}else{"Node2D"};fs::write(r.join("project.godot"),format!("[application]\nconfig/name=\"{n}\"\nrun/main_scene=\"res://main.tscn\"\n[rendering]\nrenderer/rendering_method=\"gl_compatibility\"\n")).map_err(|e|e.to_string())?;fs::write(r.join("main.tscn"),format!("[gd_scene format=3]\n\n[node name=\"{n}\" type=\"{node}\"]\n")).map_err(|e|e.to_string())?;fs::write(r.join("scripts/main.gd"),format!("extends {node}\n\nfunc _ready():\n    print(\"AI Game Maker: {prompt}\")\n")).map_err(|e|e.to_string())?;Ok(r.to_string_lossy().into())}
#[tauri::command]fn validate_project(path:String)->Result<serde_json::Value,String>{let p=PathBuf::from(path);let e=["project.godot","main.tscn","scripts/main.gd"].iter().filter(|f|!p.join(f).is_file()).map(|f|format!("Missing: {f}")).collect::<Vec<_>>();Ok(serde_json::json!({"ok":e.is_empty(),"errors":e,"warnings":[]}))}
#[tauri::command]fn godot_check(path:String)->Result<serde_json::Value,String>{let Some(g)=cmd("godot").or_else(||cmd("godot4"))else{return Ok(serde_json::json!({"ok":false,"available":false}))};let o=Command::new(g).args(["--headless","--path",&path,"--editor","--quit"]).output().map_err(|e|e.to_string())?;Ok(serde_json::json!({"ok":o.status.success(),"available":true,"code":o.status.code()}))}
#[tauri::command]fn list_plugins()->Result<Vec<String>,String>{Ok(vec![])}
#[tauri::command]fn comfyui_status()->Result<bool,String>{Ok(std::net::TcpStream::connect("127.0.0.1:8188").is_ok())}
fn main(){tauri::Builder::default().invoke_handler(tauri::generate_handler![environment_status,create_project,validate_project,godot_check,list_plugins,comfyui_status]).run(tauri::generate_context!()).expect("error while running tauri application");}